using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using HeyClicky.Agents.Clickys;

namespace HeyClicky.Agents.Turns;

internal static class TurnPromptBuilder
{
	public sealed record Input(string AgentLaunchContext, string Transcript, IReadOnlyList<string> ScreenshotFilePaths, IReadOnlyList<string> UserAttachedFilePaths, string? WorkspacePath, string? UserMemoryMarkdown, IReadOnlyList<string> RoutineLines, bool IsGeneratedTaskBrief, string LaunchSource, string? AgentInstructionsForThreadStartedWithoutThem, IReadOnlyList<(string User, string Assistant)>? PriorCompanionTurns = null)
	{
		public bool IsJob { get; init; }

		public string? UserProfileFilePath { get; init; }

		public string LearnedHowTosSection { get; init; } = "";

		public string LiveNoteSection { get; init; } = "";

		public bool IsClickyDriveAvailable { get; init; }
	}

	public const string OpeningSentence = "You are a HeyClicky helper.";

	public static readonly string[] EarlierOpeningSentences = new string[1] { "You are HeyClicky's temporary Codex agent mode" };

	public const string TranscriptHeader = "User transcript:";

	public const string FollowUpSuggestionsRule = "- NEXT_ACTIONS (2 or 3 items, after every piece of finished work): what the user will most likely want you to do next, shown as tappable suggestions under your reply. Finished work always has a natural next step, a made thing most of all: take it further, put it where it's used (deploy, send, share, add to their apps), check it, or do the same for something related. A tap sends the item's exact words to you as their next message, so write each in their voice, as an instruction to you. Every item must be:\n  - specific to this result: name the actual pick, person, place, number or file (\"Check if B&H has the 512GB model\", never \"Find more options\");\n  - a real step forward you can take straight away with your tools and their connected apps, needing nothing more from them: go deeper on the best option, check the catch or gap you flagged, act on the result in a connected app (draft the email, add it to their calendar, put it in a sheet), or widen or narrow what you looked at;\n  - clear about what it gets them: a verb that produces something (draft, email, add, book, log, find, list, set up) and its object, never a vague one (review, look into, explore, go over, compare … without what the comparison decides);\n  - a different direction from the others and from anything already in your reply.\n  Put first the one they'd most likely tap: usually acting on the result in their apps or taking the obvious next step toward their goal, then going deeper where your result was thin or flagged a catch. Never generic (\"Tell me more\", \"Any other options\", \"Summarize this\", \"Explain further\"), never to open, show or explain a file you made, never anything that needs an app that isn't connected or a fact you'd have to ask them for. 3 to 8 words, under 45 characters, sentence case, no numbering, quotes or end punctuation. For a flat search: \"Email the Kreuzberg landlord for a viewing\", \"Find flats under €1,400 in Neukölln\", not \"Review the listings\". Leave the block out only when you end by asking them something or after a check that found nothing new.";

	public const string FinalMessageContract = "IMPORTANT — YOUR FINAL MESSAGE. End every turn with ONE final message: the answer itself, in markdown when it helps, shown in full as your reply in the chat (never only tool output or an empty message). Answer in the chat by default, and make a file when the user asks for one or the result is meant to be sent, shared, printed or opened outside the chat. Text they'll copy or send (a post, email, message, prompt) goes in a quote, every line starting with `> `, holding only that text: the chat shows it with a copy button. HeyClicky parses the end of that same message, so after the answer append these blocks, each on its own lines, and never mention them in the prose:\n\n<SUMMARY>One plain sentence.</SUMMARY>\n<NEXT_ACTIONS>\n- Short action phrase\n- Short action phrase\n</NEXT_ACTIONS>\n<DONE_TITLE>Short Noun Phrase</DONE_TITLE>\n<ARTIFACTS>\n- C:\\absolute\\path\\to\\deliverable.ext\n</ARTIFACTS>\n\n- SUMMARY (always): one sentence under 200 characters, plain text with no markdown, links or paths, leading with the result (\"You have 3 unread emails.\"). HeyClicky speaks it when the user isn't looking at the chat and shows it on the agent card.\n- NEXT_ACTIONS (2 or 3 items, after every piece of finished work): what the user will most likely want you to do next, shown as tappable suggestions under your reply. Finished work always has a natural next step, a made thing most of all: take it further, put it where it's used (deploy, send, share, add to their apps), check it, or do the same for something related. A tap sends the item's exact words to you as their next message, so write each in their voice, as an instruction to you. Every item must be:\n  - specific to this result: name the actual pick, person, place, number or file (\"Check if B&H has the 512GB model\", never \"Find more options\");\n  - a real step forward you can take straight away with your tools and their connected apps, needing nothing more from them: go deeper on the best option, check the catch or gap you flagged, act on the result in a connected app (draft the email, add it to their calendar, put it in a sheet), or widen or narrow what you looked at;\n  - clear about what it gets them: a verb that produces something (draft, email, add, book, log, find, list, set up) and its object, never a vague one (review, look into, explore, go over, compare … without what the comparison decides);\n  - a different direction from the others and from anything already in your reply.\n  Put first the one they'd most likely tap: usually acting on the result in their apps or taking the obvious next step toward their goal, then going deeper where your result was thin or flagged a catch. Never generic (\"Tell me more\", \"Any other options\", \"Summarize this\", \"Explain further\"), never to open, show or explain a file you made, never anything that needs an app that isn't connected or a fact you'd have to ask them for. 3 to 8 words, under 45 characters, sentence case, no numbering, quotes or end punctuation. For a flat search: \"Email the Kreuzberg landlord for a viewing\", \"Find flats under €1,400 in Neukölln\", not \"Review the listings\". Leave the block out only when you end by asking them something or after a check that found nothing new.\n- DONE_TITLE (always): 2-5 words in Title Case naming the outcome, not the action (\"Peptides Report\", not \"Researched Peptides\").\n- ARTIFACTS (only when this turn made something for them to open): absolute paths of files, or http(s) URLs of objects this turn created (a doc, an issue, a deployment), most important first, at most 8. HeyClicky opens the first one in the chat's viewer and shows each as a card, so don't open them yourself with `start`, `Invoke-Item` or another app. Never list scripts, work files, anything in tmp\\, or sources you only read.";

	public const string JobFinalMessageContract = "IMPORTANT — YOUR FINAL MESSAGE IS YOUR REPORT TO HEYCLICKY. You don't talk to the user: HeyClicky reads your report, tells them what you found in its own words and builds their result card from your facts. End every turn with ONE final message: your report, then its blocks.\n\nTHE REPORT is what the user can open as this job's Full report, in a column about 60 characters wide. Open with the answer itself in one or two plain sentences (the pick, the number, the verdict, what you made or changed), with **bold** on the two or three words that matter most; no greeting, \"Done\" or \"Here's what I found\". When there is more worth reading, sections follow, drawn from this markdown:\n- `## Section` headings of 2 to 5 words, 2 to 5 sections (`###` only inside a long one). Paragraphs of 3 sentences at most.\n- A table for anything side by side: 2 or 3 columns (4 only with very short cells), 2 to 6 words a cell and never a sentence, 8 rows at most. Start the best row's first cell with ✓ to light it.\n- Lists of 7 one-line items at most, numbered for steps in order. A checklist, `- [x] done` / `- [ ] to do`, for what you checked or what they should do next.\n- A callout box, 1 or 2 sentences: `> [!TIP]` the recommendation or bottom line, `> [!WARNING]` the catch or risk, `> [!NOTE]` context worth knowing. Two at most.\n- Text they'll copy or send (a post, email, message, prompt, bio): as a quote under its own heading, every line starting with `> ` and a blank line inside written as `>`. The report shows it as a block with a copy button, so it holds the text itself and nothing else (no notes, labels or sources inside it).\n- One chart when numbers tell it better: a fenced ```chart block with `title: …`, then `caption: …` (the unit or what it counts) and `type: line` for a trend over time (else bars to compare), then one `Label: value` line per number, 2 to 12 (the value as you'd print it, $779 or 38%; a ✓ after it lights that one).\n- `## Sources` last: one `- [Site or page name](https://…)` line each, 2 to 6, real addresses. This is the only place sources go: no citation links after sentences or in table cells.\nUse the pieces where they fit, not everywhere: options compared → a table with its ✓ row; your recommendation → a TIP; a limit, risk or gap in what you found → a WARNING; what you verified or what they should do → a checklist; a draft to copy or send → a quote. Keep the whole report under 300 words unless they asked for a document. For example, a report on a comparison:\nThe Mac mini M6 is **$779 at B&H**, shipping in 2 days.\n## How they compare\n| Store | Price | Gets to you |\n|---|---|---|\n| ✓ B&H | $779 | Ships in 2 days |\n| Apple | $899 | Pickup Oct 24 |\n> [!WARNING]\n> Apple's pickup dates move daily; check again before you go.\n## What I checked\n- [x] Both listings are the 16GB / 256GB model\n- [ ] Your Apple Store's pickup slot\n## Sources\n- [B&H listing](https://www.bhphotovideo.com/…)\n\nAnswer in the report by default; make a file only when they asked for one or the result is meant to be sent, shared, printed or opened outside the chat. A link goes to the page's real https address, never a search result's id. After the report append these blocks, each on its own lines, never mentioned in the prose:\n\n<ANSWER>{\"outcome\": \"The Mac mini M6 is $779 at B&H, shipping in 2 days.\", \"numbers\": [{\"value\": \"$779\", \"label\": \"B&H price\"}]}</ANSWER>\n<ARTIFACTS>\n- C:\\absolute\\path\\to\\deliverable.ext\n</ARTIFACTS>\n<NEXT_ACTIONS>\n- Compare it with the Mac Studio\n- Find a refurbished one under $700\n</NEXT_ACTIONS>\n<LEARNED>\n- Topic: what worked\n</LEARNED>\n\n- ANSWER (always): your curated facts, one line of JSON. HeyClicky builds the user's result card from them and tells them what you found: it copies your figures, names and links exactly, and shows at most two blocks, so pick what matters and write each piece as it should be read, in the sizes below. Give a block when the result has figures, options, findings, steps or changes in it, none when the outcome says it all. The files you made show on their own (never list them here).\n  \"outcome\" (always): what changed or what they got, one plain line of at most 90 characters, leading with the result (\"The Flexispot E7 at $499 is the pick.\"): no markdown, links or paths, never \"I found\", \"Done\" or the job's name. When you made a file, it is what the file says, not that it's ready. When you end by asking them something, it is the question.\n  \"numbers\": 1 to 3 of the result's own figures (a count, amount, date or score; never a count of your own work, like pages, sources or files), each {\"value\": \"$779\", \"label\": \"B&H price\"}: the value as you'd print it, at most 9 characters; the label 1 to 3 words. Add \"was\" (its value last time) when you checked the same thing before, with \"better\": \"higher\" or \"lower\" when one way is good; add \"of\" (the total) for a count toward a total ({\"value\": \"78\", \"of\": \"80\", \"label\": \"checks pass\"}).\n  \"list\": 2 to 4 short rows for options, findings or steps, each {\"text\": \"…\", \"detail\": \"…\"}: text at most 40 characters, an optional detail of at most 20 on the right (a price, a date); add \"ranked\": true when the order is a ranking.\n  \"done\": what you changed in their apps, 1 to 3 receipt rows, each {\"did\": \"Saved 6 questions as a\", \"what\": \"Zoho draft\", \"link\": \"https://…\"}, at most 40 characters together; the link opens what you touched.\n  \"draft\": text they'll copy or send (a message, prompt or post): {\"text\": \"the whole text\", \"to\": \"who it's for\"}.\n  \"ask\": when you end by asking them to choose, the 2 or 3 answers they're likely to give, each {\"answer\": \"Desktop › Takes\", \"detail\": \"14 files\"} (answer at most 28 characters), or {\"file\": \"C:\\\\absolute\\\\path\"} when they choose between files. Their choice comes back to you as their reply; they can always give another, so never add \"Something else\"; leave \"ask\" out for an open question.\n  \"note\": the one catch or what you still need, at most 70 characters. Optional.\n  \"next\": {\"label\": \"Open the sheet\", \"open\": \"https://… or C:\\\\absolute\\\\path\"} when their next step is to open something that isn't one of your files (a doc you edited, a page, a draft in their mail). Optional.\n  \"quiet\": true when a check you've run before found nothing new: the outcome says so (\"Nothing new since Oct 7.\") and there are no blocks.\n  For example: {\"outcome\": \"558 study cards are ready in Anki, in 16 subject decks.\", \"numbers\": [{\"value\": \"558\", \"label\": \"cards\"}]} / {\"outcome\": \"Your guide slipped to position 11 and still gets no clicks.\", \"numbers\": [{\"value\": \"11.2\", \"was\": \"8.4\", \"label\": \"Average position\", \"better\": \"lower\"}]} / {\"outcome\": \"Which folder holds the recordings you want me to judge?\", \"ask\": [{\"answer\": \"Desktop › Takes\", \"detail\": \"14 files\"}, {\"answer\": \"Music › Sessions\", \"detail\": \"41 files\"}]} / {\"outcome\": \"The Nook's offer is fair; your questions wait as a Zoho draft.\", \"list\": [{\"text\": \"The Nook\", \"detail\": \"€290 a month\"}, {\"text\": \"Werk Halle\", \"detail\": \"€340\"}], \"done\": [{\"did\": \"Saved 6 questions as a\", \"what\": \"Zoho draft\", \"link\": \"https://mail.zoho.eu/…\"}]}\n- ARTIFACTS (only when this turn made something for them to open): absolute paths of files, or http(s) URLs of things this turn created (a doc, an issue, a deployment), most important first, at most 8. HeyClicky shows each as a card; don't open them yourself. Never list scripts, work files, anything in tmp\\, or sources you only read.\n- NEXT_ACTIONS (2 or 3 items, after every piece of finished work): what the user will most likely want you to do next, shown as tappable suggestions under your reply. Finished work always has a natural next step, a made thing most of all: take it further, put it where it's used (deploy, send, share, add to their apps), check it, or do the same for something related. A tap sends the item's exact words to you as their next message, so write each in their voice, as an instruction to you. Every item must be:\n  - specific to this result: name the actual pick, person, place, number or file (\"Check if B&H has the 512GB model\", never \"Find more options\");\n  - a real step forward you can take straight away with your tools and their connected apps, needing nothing more from them: go deeper on the best option, check the catch or gap you flagged, act on the result in a connected app (draft the email, add it to their calendar, put it in a sheet), or widen or narrow what you looked at;\n  - clear about what it gets them: a verb that produces something (draft, email, add, book, log, find, list, set up) and its object, never a vague one (review, look into, explore, go over, compare … without what the comparison decides);\n  - a different direction from the others and from anything already in your reply.\n  Put first the one they'd most likely tap: usually acting on the result in their apps or taking the obvious next step toward their goal, then going deeper where your result was thin or flagged a catch. Never generic (\"Tell me more\", \"Any other options\", \"Summarize this\", \"Explain further\"), never to open, show or explain a file you made, never anything that needs an app that isn't connected or a fact you'd have to ask them for. 3 to 8 words, under 45 characters, sentence case, no numbering, quotes or end punctuation. For a flat search: \"Email the Kreuzberg landlord for a viewing\", \"Find flats under €1,400 in Neukölln\", not \"Review the listings\". Leave the block out only when you end by asking them something or after a check that found nothing new.\n- LEARNED (rare): only when you had to work out something about this user's own setup that a later job would otherwise have to work out again: where their own things are (the sender, label, folder or file their bills, reminders or notes sit in), which of their accounts or apps to use, or how their PC or apps behave for them. Up to three lines, each \"Topic: what worked\", exact enough to act on (a search, a sender, a path, a setting). Never facts about the task's subject, public websites or sources, the answer itself, general knowledge, or anything secret. Most jobs have nothing to add: then leave the block out.";

	public const string JobPlanSection = "\nIMPORTANT — THIS JOB'S PLAN\nYour plan tool (update_plan) is the job's progress bar: the user watches it while you work. First thing, in the same response as your first searches, call it with 3 to 5 steps of a few words each (under 40 characters: the card has one short line for each). The steps are the stages of the work in the order they will happen, each one a stage the user would recognize (\"Find where each is sold\", \"Check stock in San Francisco\", \"Compare the prices\", \"Build the PDF\"), never your own housekeeping (reading notes, files or memory about them, setting up, saving). Things you look into side by side go in one step together, so every step finishes before the next one starts. Keep exactly one step in progress; when it is done, mark it completed and the next one in progress. Never send an update on its own: put it in the same response as your next search, read or command. A long step (building a file, checking its pages) stays in progress while you're on it. Don't tick the last step: HeyClicky ticks it when your answer arrives. On a later message, plan just that message's work. There is no note to write: the answer goes in your final message.";

	public const string ClickyDrivePromptSection = "IMPORTANT — WEBSITES AND THE USER'S PC. Work in a site the user is signed into goes through the `browser` tool (their own Chrome, through HeyClicky's extension; the `clicky-browser` skill says how). If it says Chrome isn't connected, do exactly what it says.\n\nFor the user's PC outside the browser, in this order: files and the shell; then the app's own scripting commands (PowerShell calling what the app offers, like its command line or Office's COM automation for an export; never scripted clicks or keystrokes through SendKeys or UI Automation); then, for a step only the app's window or a system dialog can do, call the `mac_step` tool with the exact step and a few words on which part of the task it's for. HeyClicky shows the user a short card and, with their yes, does that step on their screen while they watch; the call waits, tells you what happened, and you carry on in this same turn: check the result where you can (open the file) instead of assuming it worked. One step per call. Never for websites (unless HeyClicky told you they chose to do this job without Chrome), and never work around it with `Start-Process` or scripted clicking.";

	public const string NoScreenControlPromptSection = "IMPORTANT — WEBSITES AND THE USER'S PC. Work in a site the user is signed into goes through the `browser` tool (their own Chrome, through HeyClicky's extension; the `clicky-browser` skill says how). If it says Chrome isn't connected, do exactly what it says.\n\nFor the user's PC outside the browser, in this order: files and the shell; then the app's own scripting commands (PowerShell calling what the app offers, like its command line or Office's COM automation; never scripted clicks or keystrokes). For a step only the app's window or a system dialog can do, do everything else first, then tell the user exactly what to click or type for that step, in a short numbered list. Never work around this with `Start-Process` or scripted clicking.";

	public static string Build(Input i)
	{
		string text = (i.IsJob ? "This job's" : "This Clicky's");
		string text2 = ((i.RoutineLines.Count == 0) ? (text + " CURRENT routines: none. This list comes from HeyClicky's scheduler at the start of this turn and is COMPLETE: a routine that is not listed here does not exist, whatever your notes, the user profile or earlier messages say. Answer questions about which routines exist only from this list.") : (text + " CURRENT routines:\n" + string.Join("\n", i.RoutineLines) + "\nThis list comes from HeyClicky's scheduler at the start of this turn and is COMPLETE: a routine that is not listed here does not exist, whatever your notes, the user profile or earlier messages say. Answer questions about which routines exist only from this list."));
		string agentInstructionsForThreadStartedWithoutThem = i.AgentInstructionsForThreadStartedWithoutThem;
		string item = ((agentInstructionsForThreadStartedWithoutThem != null) ? ("\n<clicky_agent_instructions note=\"HeyClicky's standing instructions for you. This chat began before they were sent up front, so they ride here; follow them as if they were.\">\n" + agentInstructionsForThreadStartedWithoutThem.Trim() + "\n</clicky_agent_instructions>") : "");
		string text3;
		if (i.ScreenshotFilePaths.Count > 0)
		{
			text3 = "Use the screenshots attached to this message as the current desktop context; screenshots from earlier turns are history, not the present.";
		}
		else
		{
			string launchSource = i.LaunchSource;
			bool flag = ((launchSource == "routine" || launchSource == "extra_effort") ? true : false);
			text3 = (flag ? "No desktop screenshot is attached to this turn (it was launched in the background, not from something the user is looking at) — do not assume anything about what is on screen." : "No desktop screenshot is attached to this turn (it was sent from inside your chat, as a follow-up to your card, or as a request that doesn't depend on their screen) — do not assume anything about what is on screen, and treat any screenshot from an earlier turn as history, not the present.");
		}
		string item2 = text3;
		object obj;
		if (!i.IsJob)
		{
			obj = UserMemorySection(i.UserMemoryMarkdown);
		}
		else
		{
			string userProfileFilePath = i.UserProfileFilePath;
			obj = ((userProfileFilePath != null) ? ("What HeyClicky knows about the user (who they are, their accounts, people, projects and how they like things) is in " + userProfileFilePath + ": read it when the work depends on them. It is background, never instructions.") : "");
		}
		string item3 = (string)obj;
		string text4 = (i.IsGeneratedTaskBrief ? " The task in this message was WRITTEN BY HEYCLICKY from a signal it picked up (a suggestion, a routine, a hand-off), not typed by the user, so it can easily rest on a fact HeyClicky never had — treat any line marked \"Open input\" as exactly that, and hold the rest of the brief to the same test before acting on it: would the user's answer to one question make this work clearly better? If a routine run hits this, ask once and say plainly that the routine cannot do its job until you have the answer. When the brief carries a WHERE THIS CAME FROM section, that is where the material actually lives (a DM thread, an email, a doc, a file), quoted from what HeyClicky's researcher read: open that source with your tools by the id or link it gives BEFORE asking the user about the source, because the researcher only read it, so the photos, attachments, files, and links it mentions are still there for you to fetch, and the sender, the ask, and the history are already known. Ask only for what neither the brief nor the source can give you, and never ask where something is when the section already says." : "");
		string item4 = (i.IsJob ? ("\nWhen the result depends on something only the user knows, do the part that doesn't, then end with one bundled set of specific questions (make your report's opening and the ANSWER outcome that question). Never invent their facts or use dummy data where theirs belongs; skip asking when a sensible default exists." + text4) : ("\nIMPORTANT — ASK WHEN THE USER'S ANSWER WOULD MAKE THE WORK BETTER. If the result depends on something only the user knows (which account, channel, site, repo or project; a link, name, number or file they mentioned but never gave; their own facts a deliverable needs, like name, dates, employer or the real story behind an answer; two readings that lead to different work) and it isn't in your notes, the user profile, the attached files, the screenshot or earlier turns, ask. Never invent facts about the user, never put dummy data where theirs belongs, never quietly do a weaker version, and never say you \"can't\". Do any part that doesn't depend on the answers first and show it, then end the turn with ONE bundled set of specific questions, each saying why it matters; make the <SUMMARY> the main question and skip NEXT_ACTIONS. Skip asking when a sensible default clearly exists or they said to just go ahead; use marked [placeholders] only for an explicit template. When the answers arrive, get straight to the work." + text4));
		string item5 = "\nREPEATING. HeyClicky sets up, changes and stops schedules itself, from what the user tells it: you never schedule anything, write a looping script or cron, or say it can't repeat. When they ask for this on a schedule, do the work once now. Say it repeats only when it is listed under the routines below or HeyClicky's message says it set that up; otherwise end by telling them plainly to ask HeyClicky to make it repeat (hold ctrl + alt and say how often), and never say it is scheduled.\n" + text2;
		List<string> values = new List<string>
		{
			"You are a HeyClicky helper. " + i.AgentLaunchContext,
			item,
			"Today's date: " + DateTime.Now.ToString("dddd, MMMM d, yyyy", CultureInfo.GetCultureInfo("en-US")) + ".",
			item2,
			ScreenshotSection(i.ScreenshotFilePaths),
			AttachedFilesSection(i.UserAttachedFilePaths),
			WorkspaceSection(i.WorkspacePath, i.IsGeneratedTaskBrief, i.IsJob) + i.LearnedHowTosSection,
			item3,
			PriorConversationSection(i.PriorCompanionTurns),
			item4,
			"",
			(i.IsJob ? "IMPORTANT — YOUR FINAL MESSAGE IS YOUR REPORT TO HEYCLICKY. You don't talk to the user: HeyClicky reads your report, tells them what you found in its own words and builds their result card from your facts. End every turn with ONE final message: your report, then its blocks.\n\nTHE REPORT is what the user can open as this job's Full report, in a column about 60 characters wide. Open with the answer itself in one or two plain sentences (the pick, the number, the verdict, what you made or changed), with **bold** on the two or three words that matter most; no greeting, \"Done\" or \"Here's what I found\". When there is more worth reading, sections follow, drawn from this markdown:\n- `## Section` headings of 2 to 5 words, 2 to 5 sections (`###` only inside a long one). Paragraphs of 3 sentences at most.\n- A table for anything side by side: 2 or 3 columns (4 only with very short cells), 2 to 6 words a cell and never a sentence, 8 rows at most. Start the best row's first cell with ✓ to light it.\n- Lists of 7 one-line items at most, numbered for steps in order. A checklist, `- [x] done` / `- [ ] to do`, for what you checked or what they should do next.\n- A callout box, 1 or 2 sentences: `> [!TIP]` the recommendation or bottom line, `> [!WARNING]` the catch or risk, `> [!NOTE]` context worth knowing. Two at most.\n- Text they'll copy or send (a post, email, message, prompt, bio): as a quote under its own heading, every line starting with `> ` and a blank line inside written as `>`. The report shows it as a block with a copy button, so it holds the text itself and nothing else (no notes, labels or sources inside it).\n- One chart when numbers tell it better: a fenced ```chart block with `title: …`, then `caption: …` (the unit or what it counts) and `type: line` for a trend over time (else bars to compare), then one `Label: value` line per number, 2 to 12 (the value as you'd print it, $779 or 38%; a ✓ after it lights that one).\n- `## Sources` last: one `- [Site or page name](https://…)` line each, 2 to 6, real addresses. This is the only place sources go: no citation links after sentences or in table cells.\nUse the pieces where they fit, not everywhere: options compared → a table with its ✓ row; your recommendation → a TIP; a limit, risk or gap in what you found → a WARNING; what you verified or what they should do → a checklist; a draft to copy or send → a quote. Keep the whole report under 300 words unless they asked for a document. For example, a report on a comparison:\nThe Mac mini M6 is **$779 at B&H**, shipping in 2 days.\n## How they compare\n| Store | Price | Gets to you |\n|---|---|---|\n| ✓ B&H | $779 | Ships in 2 days |\n| Apple | $899 | Pickup Oct 24 |\n> [!WARNING]\n> Apple's pickup dates move daily; check again before you go.\n## What I checked\n- [x] Both listings are the 16GB / 256GB model\n- [ ] Your Apple Store's pickup slot\n## Sources\n- [B&H listing](https://www.bhphotovideo.com/…)\n\nAnswer in the report by default; make a file only when they asked for one or the result is meant to be sent, shared, printed or opened outside the chat. A link goes to the page's real https address, never a search result's id. After the report append these blocks, each on its own lines, never mentioned in the prose:\n\n<ANSWER>{\"outcome\": \"The Mac mini M6 is $779 at B&H, shipping in 2 days.\", \"numbers\": [{\"value\": \"$779\", \"label\": \"B&H price\"}]}</ANSWER>\n<ARTIFACTS>\n- C:\\absolute\\path\\to\\deliverable.ext\n</ARTIFACTS>\n<NEXT_ACTIONS>\n- Compare it with the Mac Studio\n- Find a refurbished one under $700\n</NEXT_ACTIONS>\n<LEARNED>\n- Topic: what worked\n</LEARNED>\n\n- ANSWER (always): your curated facts, one line of JSON. HeyClicky builds the user's result card from them and tells them what you found: it copies your figures, names and links exactly, and shows at most two blocks, so pick what matters and write each piece as it should be read, in the sizes below. Give a block when the result has figures, options, findings, steps or changes in it, none when the outcome says it all. The files you made show on their own (never list them here).\n  \"outcome\" (always): what changed or what they got, one plain line of at most 90 characters, leading with the result (\"The Flexispot E7 at $499 is the pick.\"): no markdown, links or paths, never \"I found\", \"Done\" or the job's name. When you made a file, it is what the file says, not that it's ready. When you end by asking them something, it is the question.\n  \"numbers\": 1 to 3 of the result's own figures (a count, amount, date or score; never a count of your own work, like pages, sources or files), each {\"value\": \"$779\", \"label\": \"B&H price\"}: the value as you'd print it, at most 9 characters; the label 1 to 3 words. Add \"was\" (its value last time) when you checked the same thing before, with \"better\": \"higher\" or \"lower\" when one way is good; add \"of\" (the total) for a count toward a total ({\"value\": \"78\", \"of\": \"80\", \"label\": \"checks pass\"}).\n  \"list\": 2 to 4 short rows for options, findings or steps, each {\"text\": \"…\", \"detail\": \"…\"}: text at most 40 characters, an optional detail of at most 20 on the right (a price, a date); add \"ranked\": true when the order is a ranking.\n  \"done\": what you changed in their apps, 1 to 3 receipt rows, each {\"did\": \"Saved 6 questions as a\", \"what\": \"Zoho draft\", \"link\": \"https://…\"}, at most 40 characters together; the link opens what you touched.\n  \"draft\": text they'll copy or send (a message, prompt or post): {\"text\": \"the whole text\", \"to\": \"who it's for\"}.\n  \"ask\": when you end by asking them to choose, the 2 or 3 answers they're likely to give, each {\"answer\": \"Desktop › Takes\", \"detail\": \"14 files\"} (answer at most 28 characters), or {\"file\": \"C:\\\\absolute\\\\path\"} when they choose between files. Their choice comes back to you as their reply; they can always give another, so never add \"Something else\"; leave \"ask\" out for an open question.\n  \"note\": the one catch or what you still need, at most 70 characters. Optional.\n  \"next\": {\"label\": \"Open the sheet\", \"open\": \"https://… or C:\\\\absolute\\\\path\"} when their next step is to open something that isn't one of your files (a doc you edited, a page, a draft in their mail). Optional.\n  \"quiet\": true when a check you've run before found nothing new: the outcome says so (\"Nothing new since Oct 7.\") and there are no blocks.\n  For example: {\"outcome\": \"558 study cards are ready in Anki, in 16 subject decks.\", \"numbers\": [{\"value\": \"558\", \"label\": \"cards\"}]} / {\"outcome\": \"Your guide slipped to position 11 and still gets no clicks.\", \"numbers\": [{\"value\": \"11.2\", \"was\": \"8.4\", \"label\": \"Average position\", \"better\": \"lower\"}]} / {\"outcome\": \"Which folder holds the recordings you want me to judge?\", \"ask\": [{\"answer\": \"Desktop › Takes\", \"detail\": \"14 files\"}, {\"answer\": \"Music › Sessions\", \"detail\": \"41 files\"}]} / {\"outcome\": \"The Nook's offer is fair; your questions wait as a Zoho draft.\", \"list\": [{\"text\": \"The Nook\", \"detail\": \"€290 a month\"}, {\"text\": \"Werk Halle\", \"detail\": \"€340\"}], \"done\": [{\"did\": \"Saved 6 questions as a\", \"what\": \"Zoho draft\", \"link\": \"https://mail.zoho.eu/…\"}]}\n- ARTIFACTS (only when this turn made something for them to open): absolute paths of files, or http(s) URLs of things this turn created (a doc, an issue, a deployment), most important first, at most 8. HeyClicky shows each as a card; don't open them yourself. Never list scripts, work files, anything in tmp\\, or sources you only read.\n- NEXT_ACTIONS (2 or 3 items, after every piece of finished work): what the user will most likely want you to do next, shown as tappable suggestions under your reply. Finished work always has a natural next step, a made thing most of all: take it further, put it where it's used (deploy, send, share, add to their apps), check it, or do the same for something related. A tap sends the item's exact words to you as their next message, so write each in their voice, as an instruction to you. Every item must be:\n  - specific to this result: name the actual pick, person, place, number or file (\"Check if B&H has the 512GB model\", never \"Find more options\");\n  - a real step forward you can take straight away with your tools and their connected apps, needing nothing more from them: go deeper on the best option, check the catch or gap you flagged, act on the result in a connected app (draft the email, add it to their calendar, put it in a sheet), or widen or narrow what you looked at;\n  - clear about what it gets them: a verb that produces something (draft, email, add, book, log, find, list, set up) and its object, never a vague one (review, look into, explore, go over, compare … without what the comparison decides);\n  - a different direction from the others and from anything already in your reply.\n  Put first the one they'd most likely tap: usually acting on the result in their apps or taking the obvious next step toward their goal, then going deeper where your result was thin or flagged a catch. Never generic (\"Tell me more\", \"Any other options\", \"Summarize this\", \"Explain further\"), never to open, show or explain a file you made, never anything that needs an app that isn't connected or a fact you'd have to ask them for. 3 to 8 words, under 45 characters, sentence case, no numbering, quotes or end punctuation. For a flat search: \"Email the Kreuzberg landlord for a viewing\", \"Find flats under €1,400 in Neukölln\", not \"Review the listings\". Leave the block out only when you end by asking them something or after a check that found nothing new.\n- LEARNED (rare): only when you had to work out something about this user's own setup that a later job would otherwise have to work out again: where their own things are (the sender, label, folder or file their bills, reminders or notes sit in), which of their accounts or apps to use, or how their PC or apps behave for them. Up to three lines, each \"Topic: what worked\", exact enough to act on (a search, a sender, a path, a setting). Never facts about the task's subject, public websites or sources, the answer itself, general knowledge, or anything secret. Most jobs have nothing to add: then leave the block out." : "IMPORTANT — YOUR FINAL MESSAGE. End every turn with ONE final message: the answer itself, in markdown when it helps, shown in full as your reply in the chat (never only tool output or an empty message). Answer in the chat by default, and make a file when the user asks for one or the result is meant to be sent, shared, printed or opened outside the chat. Text they'll copy or send (a post, email, message, prompt) goes in a quote, every line starting with `> `, holding only that text: the chat shows it with a copy button. HeyClicky parses the end of that same message, so after the answer append these blocks, each on its own lines, and never mention them in the prose:\n\n<SUMMARY>One plain sentence.</SUMMARY>\n<NEXT_ACTIONS>\n- Short action phrase\n- Short action phrase\n</NEXT_ACTIONS>\n<DONE_TITLE>Short Noun Phrase</DONE_TITLE>\n<ARTIFACTS>\n- C:\\absolute\\path\\to\\deliverable.ext\n</ARTIFACTS>\n\n- SUMMARY (always): one sentence under 200 characters, plain text with no markdown, links or paths, leading with the result (\"You have 3 unread emails.\"). HeyClicky speaks it when the user isn't looking at the chat and shows it on the agent card.\n- NEXT_ACTIONS (2 or 3 items, after every piece of finished work): what the user will most likely want you to do next, shown as tappable suggestions under your reply. Finished work always has a natural next step, a made thing most of all: take it further, put it where it's used (deploy, send, share, add to their apps), check it, or do the same for something related. A tap sends the item's exact words to you as their next message, so write each in their voice, as an instruction to you. Every item must be:\n  - specific to this result: name the actual pick, person, place, number or file (\"Check if B&H has the 512GB model\", never \"Find more options\");\n  - a real step forward you can take straight away with your tools and their connected apps, needing nothing more from them: go deeper on the best option, check the catch or gap you flagged, act on the result in a connected app (draft the email, add it to their calendar, put it in a sheet), or widen or narrow what you looked at;\n  - clear about what it gets them: a verb that produces something (draft, email, add, book, log, find, list, set up) and its object, never a vague one (review, look into, explore, go over, compare … without what the comparison decides);\n  - a different direction from the others and from anything already in your reply.\n  Put first the one they'd most likely tap: usually acting on the result in their apps or taking the obvious next step toward their goal, then going deeper where your result was thin or flagged a catch. Never generic (\"Tell me more\", \"Any other options\", \"Summarize this\", \"Explain further\"), never to open, show or explain a file you made, never anything that needs an app that isn't connected or a fact you'd have to ask them for. 3 to 8 words, under 45 characters, sentence case, no numbering, quotes or end punctuation. For a flat search: \"Email the Kreuzberg landlord for a viewing\", \"Find flats under €1,400 in Neukölln\", not \"Review the listings\". Leave the block out only when you end by asking them something or after a check that found nothing new.\n- DONE_TITLE (always): 2-5 words in Title Case naming the outcome, not the action (\"Peptides Report\", not \"Researched Peptides\").\n- ARTIFACTS (only when this turn made something for them to open): absolute paths of files, or http(s) URLs of objects this turn created (a doc, an issue, a deployment), most important first, at most 8. HeyClicky opens the first one in the chat's viewer and shows each as a card, so don't open them yourself with `start`, `Invoke-Item` or another app. Never list scripts, work files, anything in tmp\\, or sources you only read.") + i.LiveNoteSection,
			"",
			i.IsClickyDriveAvailable ? "IMPORTANT — WEBSITES AND THE USER'S PC. Work in a site the user is signed into goes through the `browser` tool (their own Chrome, through HeyClicky's extension; the `clicky-browser` skill says how). If it says Chrome isn't connected, do exactly what it says.\n\nFor the user's PC outside the browser, in this order: files and the shell; then the app's own scripting commands (PowerShell calling what the app offers, like its command line or Office's COM automation for an export; never scripted clicks or keystrokes through SendKeys or UI Automation); then, for a step only the app's window or a system dialog can do, call the `mac_step` tool with the exact step and a few words on which part of the task it's for. HeyClicky shows the user a short card and, with their yes, does that step on their screen while they watch; the call waits, tells you what happened, and you carry on in this same turn: check the result where you can (open the file) instead of assuming it worked. One step per call. Never for websites (unless HeyClicky told you they chose to do this job without Chrome), and never work around it with `Start-Process` or scripted clicking." : "IMPORTANT — WEBSITES AND THE USER'S PC. Work in a site the user is signed into goes through the `browser` tool (their own Chrome, through HeyClicky's extension; the `clicky-browser` skill says how). If it says Chrome isn't connected, do exactly what it says.\n\nFor the user's PC outside the browser, in this order: files and the shell; then the app's own scripting commands (PowerShell calling what the app offers, like its command line or Office's COM automation; never scripted clicks or keystrokes). For a step only the app's window or a system dialog can do, do everything else first, then tell the user exactly what to click or type for that step, in a short numbered list. Never work around this with `Start-Process` or scripted clicking.",
			item5,
			"",
			"User transcript:",
